Lemma w_cs_ok_agree : forall E E' cs R FULL model,
  env_agree (nxt cs) E E' -> fresh_ok nx0 cs = true -> CSOK E cs R FULL model -> CSOK E' cs R FULL model.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S20!1+0!1,1|600;|30;$E;R+^N$E';R+^N$cs;R+eB$R;R!2'^P!1,1|21;0$FULL;R%~R0!1+`D!1+0!1,11$model;R+eC$~R!3'`G!1'eN#4#6#5$~R!3+3+^E!2'eO/nx0;#5,^F$~R!;+eD/SEGS;/A;/LIMIT;/SINV;/argH;/FS0;#8#6#5#4#3!B'eP/SEGS;/A;/nx0;/LIMIT;/SINV;/argH;/argH_agree;/SINV_agree;/FS0;#9#8#7#6#5#4#3#2#1").
Qed.

Lemma w_hid_agree : forall b E E' cs model,
  env_agree b E E' -> (nx0 <= b)%nat -> pairs_vars_lt b (a_vis cs ++ a_ghost cs) = true ->
  HID E' cs model = HID E cs model.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$b;R+2$E;R+^N$E';R+^N$cs;R+eB$model;R+eC$~R!3'`G#5#4#3$~R!2+`2/nx0;#6$~R!3+3+^E!2'eQ#7!3'cW!2+dC+^O+^O!1'eR#4!1'eS#4,^F!<'eT/A;/nx0;/argH;/argH_agree;#8#7#6#5#4#3#2#1").
Qed.

Lemma w_cs_ok_frame : forall E cs R FULL model ss' R' FULL' model',
  CSOK E cs R FULL model -> same_but_materialized model model' -> MInv (allowA A E cs) model' ->
  regs_ok E (s_regs ss') R' -> s_log ss' = [] ->
  know_ok SEGS E (MR E cs model FULL') (s_know ss') ->
  (forall a, HID E cs model a = true -> FULL' a = FULL a) ->
  CSOK E (with_ss cs ss') R' FULL' model'.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S50!1+0!1,1|600;!2'^P!1,1|21;0|30;!1+`D!1+0!1,12%~R03$E;R+^N$cs;R+eB$R;R1$FULL;R4$model;R+eC$ss';R+eU$R';R1$FULL';R4$model';R+eC$~R!;+eD/SEGS;/A;/LIMIT;/SINV;/argH;/FS0;#9#8#7#6#5$~R!2'eV#6#2$~R!2+eW!3'eX/A;#;#:#3$~R!3'_7#<!1'eY#7#6$~R!3+3!1+\+eZ!1'e[#8!1,[+eZ$~R!4'b\/SEGS;#>!6'e\/A;/argH;#>#=#:#7!1'f0#9$~R%a;R0%~R!3+3+^E!6'f1/A;/argH;#@#?#<#1,^F!3+33!1#:#2!1#>#2!G'f2/SEGS;/A;/LIMIT;/SINV;/argH;/SINV_frame;/FS0;#@#?#>#=#<#;#:#9#8#7#6#5#4#3#2#1").
Qed.

